// 报价绑定完整World读戳与原本人节点；新请求不能把旧照护结果冒成本次完成。
#include "child_care_relief_commands.hpp"
#include "child_care_relief_resources.hpp"
#include "succession_personal_assets.hpp"
#include <tuple>
namespace hanmo::resident {namespace {
bool shape(const ChildCareReliefCommand& q){auto id=[](const StableId& s){return !s.empty()&&s.size()<=256;};
    if(q.kind=="family_care_relief_accept")return id(q.offer_id)&&id(q.child_actor_id)&&q.accepted_id.empty()&&q.action_id.empty();
    if(q.kind=="family_care_relief_withdraw"||q.kind=="family_child_care_relief")return q.offer_id.empty()&&q.child_actor_id.empty()&&id(q.accepted_id)&&q.action_id.empty();
    if(q.kind=="family_care_relief_cancel")return q.offer_id.empty()&&q.child_actor_id.empty()&&q.accepted_id.empty()&&id(q.action_id);return false;
}
bool same(const ChildCareReliefCommand& a,const ChildCareReliefCommand& b){return std::tie(a.kind,a.offer_id,a.child_actor_id,a.accepted_id,a.action_id)==std::tie(b.kind,b.offer_id,b.child_actor_id,b.accepted_id,b.action_id);}
bool identity(const WorldIdentity& a,const WorldIdentity& b){return std::tie(a.world_id,a.execution_epoch,a.tick,a.revision)==std::tie(b.world_id,b.execution_epoch,b.tick,b.revision);}
bool same(const ChildCareReliefActionQuote& a,const ChildCareReliefActionQuote& b){return identity(a.identity,b.identity)&&std::tie(a.accepted_id,a.provider_actor_id,a.child_actor_id,a.place_id,a.duration,a.period_index,a.food_per_period)==std::tie(b.accepted_id,b.provider_actor_id,b.child_actor_id,b.place_id,b.duration,b.period_index,b.food_per_period);}
}
Outcome<ChildCareReliefCommand> decode_child_care_relief_command(const StableId& kind,const BoundaryValue& args){try{using namespace boundary;auto unique=validate_succession_json_unique(args);if(!unique.ok)return {false,{},unique.error};ChildCareReliefCommand q;q.kind=kind;
    if(kind=="family_care_relief_accept"){fields(args,{"offer_id","child_actor_id"},{},kind);q.offer_id=get_string(args,"offer_id","");q.child_actor_id=get_string(args,"child_actor_id","");}
    else if(kind=="family_care_relief_withdraw"||kind=="family_child_care_relief"){fields(args,{"accepted_id"},{},kind);q.accepted_id=get_string(args,"accepted_id","");}
    else if(kind=="family_care_relief_cancel"){fields(args,{"action_id"},{},kind);q.action_id=get_string(args,"action_id","");}
    else fail("UnknownChildCareReliefCommand",kind);if(!shape(q))fail("InvalidChildCareReliefCommand",kind);return {true,std::move(q),{}};
}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Outcome<ChildCareReliefCommandQuote> preview_child_care_relief_command(const CommonStore& c,const InteractionState& meeting,const InteractionCatalog& interactions,const InteractionAccess& contact,const ChildCareReliefCatalog& catalog,const FamilyBirthState& births,const FamilyDeathState& life,const ChildCareReliefState& state,const ChildCareReliefAccess& access,const StableId& actor,const ChildCareReliefCommand& command){
    auto bad=[](const StableId& code)->Outcome<ChildCareReliefCommandQuote>{return {false,{},common_failure(code).error};};if(!catalog.enabled)return bad("ChildCareReliefProfileRequired");if(!shape(command))return bad("InvalidChildCareReliefCommand");const auto* who=c.actor(actor);if(!who||!who->alive||!who->available)return bad("ChildCareReliefParticipantUnavailable");
    const bool care=command.kind=="family_child_care_relief",cancel=command.kind=="family_care_relief_cancel";if(!care&&actor!=c.state().metadata.player_actor_id)return bad("ChildCareReliefPersonalDecisionRequired");if(!cancel&&!who->action_id.empty())return bad("ChildCareReliefParticipantUnavailable");
    auto history=validate_child_care_relief(c,interactions,catalog,births,life,state,access);if(!history.ok)return {false,{},history.error};ChildCareReliefCommandQuote quote{c.state().identity,command,{},{}};
    if(care){auto from=preview_child_care_relief_action(c,interactions,catalog,births,life,state,access,actor,command.accepted_id);if(!from.ok)return {false,{},from.error};quote.care=std::move(from.value);return {true,std::move(quote),{}};}
    if(cancel){const auto* start=state.starts.find(command.action_id);const auto* original=c.action(command.action_id);if(!start||start->provider_actor_id!=actor||!original||original->kind!="family_child_care_relief"||original->actor_id!=actor||who->action_id!=command.action_id||history.value.completed_actions.count(command.action_id))return bad("ChildCareReliefOriginalActionRequired");return {true,std::move(quote),{}};}
    if(!access.decision_maker_before)return bad("ChildCareReliefDecisionHistoryRequired");auto valid=access.decision_maker_before(actor,c.tick(),{});if(!valid.ok)return {false,{},valid.error};
    if(command.kind=="family_care_relief_withdraw"){const auto* accepted=state.agreements.find(command.accepted_id);if(!accepted||history.value.closed_agreements.count(command.accepted_id))return bad("ChildCareReliefActiveAgreementRequired");if(actor!=accepted->source.parent_actor_id&&actor!=accepted->source.provider_actor_id)return bad("ChildCareReliefPersonalDecisionRequired");if(history.value.pending_by_agreement.find(command.accepted_id))return bad("ChildCareReliefActionPending");return {true,std::move(quote),{}};}
    if(history.value.active_by_child.find(command.child_actor_id))return bad("ChildCareReliefAlreadyActive");auto source=preview_child_care_relief_source(c,meeting,interactions,contact,catalog,births,life,actor,command.child_actor_id,command.offer_id);if(!source.ok)return {false,{},source.error};valid=access.decision_maker_before(source.value.source.provider_actor_id,c.tick(),{});if(!valid.ok)return {false,{},valid.error};auto supply=preview_child_care_relief_supply(c,source.value.source);if(!supply.ok)return {false,{},supply.error};quote.source=std::move(source.value);return {true,std::move(quote),{}};
}
Status revalidate_child_care_relief_quote(const CommonStore& c,const InteractionState& meeting,const InteractionCatalog& interactions,const InteractionAccess& contact,const ChildCareReliefCatalog& catalog,const FamilyBirthState& births,const FamilyDeathState& life,const ChildCareReliefState& state,const ChildCareReliefAccess& access,const StableId& actor,const ChildCareReliefCommand& command,const ChildCareReliefCommandQuote& quote){
    if(!same(command,quote.command)||!identity(c.state().identity,quote.identity))return common_failure("StaleChildCareReliefQuote");auto fresh=preview_child_care_relief_command(c,meeting,interactions,contact,catalog,births,life,state,access,actor,command);if(!fresh.ok)return {false,{},fresh.error};if(bool(fresh.value.source)!=bool(quote.source)||bool(fresh.value.care)!=bool(quote.care)||(quote.source&&!child_care_relief_source_equal(fresh.value.source->source,quote.source->source))||(quote.care&&!same(*fresh.value.care,*quote.care)))return common_failure("ChildCareReliefQuoteSourceChanged");return common_success();
}
Outcome<ChildCareReliefCommandResult> apply_child_care_relief_command_in_candidate(CommonStore& c,const InteractionState& meeting,const InteractionCatalog& interactions,const InteractionAccess& contact,const ChildCareReliefCatalog& catalog,const FamilyBirthState& births,const FamilyDeathState& life,ChildCareReliefState& state,const ChildCareReliefAccess& access,const StableId& actor,const ChildCareReliefCommand& command,const ChildCareReliefCommandQuote& quote){
    auto valid=revalidate_child_care_relief_quote(c,meeting,interactions,contact,catalog,births,life,state,access,actor,command,quote);if(!valid.ok)return {false,{},valid.error};if(command.kind=="family_child_care_relief")return {false,{},common_failure("ChildCareReliefTimedActionRequired").error};ChildCareReliefCommandResult result;result.effect.actor_id=actor;result.effect.player_actor_id=c.state().metadata.player_actor_id;result.effect.success=true;
    if(command.kind=="family_care_relief_cancel"){auto action=*c.action(command.action_id);auto ended=cancel_child_care_relief_action_in_candidate(c,interactions,catalog,births,life,state,access,actor,action);if(!ended.ok)return {false,{},ended.error};result.release_action_id=action.id;result.effect.fact_id=ended.value.fact_id;return {true,std::move(result),{}};}
    auto recorded=command.kind=="family_care_relief_accept"?accept_child_care_relief_in_candidate(c,meeting,interactions,contact,catalog,births,life,state,access,*quote.source):withdraw_child_care_relief_in_candidate(c,interactions,catalog,births,life,state,access,actor,command.accepted_id);if(!recorded.ok)return {false,{},recorded.error};result.effect.fact_id=recorded.value;return {true,std::move(result),{}};
}
BoundaryValue encode_child_care_relief_quote(const ChildCareReliefCommandQuote& q){using V=BoundaryValue;return boundary::obj({{"ok",V{true}},{"kind",V{q.command.kind}},{"duration",V{q.care?q.care->duration:Integer{0}}},{"new_provider_food_reserved",V{q.source?q.source->source.terms.food_per_period*q.source->source.terms.prepaid_periods:Integer{0}}},{"food_on_completion",V{q.care?q.care->food_per_period:Integer{0}}},{"original_birth_hold_released",V{false}},{"scope",V{"finite_voluntary_care_own_food"}}});}
Status validate_child_care_relief_command_receipt(const ChildCareReliefState& state,const StableId& kind,const StableId& actor,Integer tick,const FamilyEffect& receipt){
    if(receipt.success!=std::optional<bool>{true}||receipt.actor_id!=std::optional<StableId>{actor}||receipt.player_actor_id!=receipt.actor_id||!receipt.fact_id||receipt.already_completed||receipt.code||receipt.heir_actor_id)return common_failure("InvalidChildCareReliefCommandReceipt");
    if(kind=="family_care_relief_accept"){const auto* row=state.agreements.find(*receipt.fact_id);return row&&row->source.parent_actor_id==actor&&row->source.tick==tick?common_success():common_failure("ChildCareReliefReceiptSourceMismatch");}
    if(kind=="family_care_relief_withdraw"){const auto* row=state.closures.find(*receipt.fact_id);return row&&row->actor_id==actor&&row->tick==tick&&(row->reason=="parent_withdrew"||row->reason=="provider_withdrew")?common_success():common_failure("ChildCareReliefReceiptSourceMismatch");}
    if(kind=="family_care_relief_cancel"){const auto* row=state.care.find(*receipt.fact_id);return row&&row->provider_actor_id==actor&&row->tick==tick&&row->outcome=="cancelled"&&row->code=="CareReliefProviderStopped"?common_success():common_failure("ChildCareReliefReceiptSourceMismatch");}
    return common_failure("UnknownChildCareReliefCommand");
}
}
